import org.apache.commons.lang3.ArrayUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class ClassUtils_toClass_TriageGen0Test {

    @Test
    public void testToClass_NullInput() {
        Class<?>[] result = ClassUtils.toClass(null);
        assertNull("If input is null, return value should be null", result);
    }

    @Test
    public void testToClass_EmptyArray() {
        Object[] input = new Object[0];
        Class<?>[] result = ClassUtils.toClass(input);
        assertArrayEquals("If input is empty, return ArrayUtils.EMPTY_CLASS_ARRAY", 
                ArrayUtils.EMPTY_CLASS_ARRAY, result);
    }

    @Test
    public void testToClass_SingleElement() {
        Object[] input = {"Hello"};
        Class<?>[] expected = {String.class};
        Class<?>[] result = ClassUtils.toClass(input);
        assertArrayEquals("Should correctly convert single element array", expected, result);
    }

    @Test
    public void testToClass_MultipleElements() {
        Object[] input = {1, 2.5, true, 'a'};
        Class<?>[] expected = {Integer.class, Double.class, Boolean.class, Character.class};
        Class<?>[] result = ClassUtils.toClass(input);
        assertArrayEquals("Should correctly convert multiple element array", expected, result);
    }

    @Test
    public void testToClass_MixedTypes() {
        Object[] input = {new Object(), "string", 10L};
        Class<?>[] expected = {Object.class, String.class, Long.class};
        Class<?>[] result = ClassUtils.toClass(input);
        assertArrayEquals("Should handle mixed object types", expected, result);
    }

    @Test
    public void testToClass_NullElementInArray() {
        // Note: The implementation calls array[i].getClass(). 
        // If an element in the array is null, it will throw a NullPointerException.
        // This test documents that behavior.
        Object[] input = {new Object(), null};
        try {
            ClassUtils.toClass(input);
        } catch (NullPointerException e) {
            // Expected behavior based on the provided implementation
        }
    }
}
